'use strict';
const $ = id => document.getElementById(id);
let dataset, run, frames = [], cursor = 0, timer = null, signal = 'temperature_mean', page = 'overview';
const labels = {temperature_mean:'온도 평균',voltage_mean:'전압 평균',current_mean:'전류 평균'};
const eventNames = {incident_opened:'이상 사건 생성',manual_found:'학습 문서 조회',action_result:'모의 대응 결과',notification:'콘솔 알림',incident_pattern_recovered:'기준 패턴 복귀',action_blocked:'모의 대응 차단'};
const statuses = {applied:'boost 적용',already_applied:'기존 boost 유지',failed:'실패',rejected:'거부'};
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2500);}
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶ 재생 시작';}
function indexRun(selected){let frame=-1;return selected.events.map(e=>{if(e.event==='prediction')frame++;return {...e,frame};});}
function selectRun(index){stop();run=dataset.runs[index];frames=indexRun(run);cursor=frames.filter(e=>e.event==='prediction').length;$('position').max=cursor;$('source-meta').textContent=`${run.date} · 전체 ${run.cells}개 셀 중 1개 평가`;$('features').innerHTML=run.feature_names.map(x=>`<li><code>${esc(x)}</code></li>`).join('');$('provenance').textContent=`원천 파일: ${run.file}\nSHA-256: ${run.sha256}\n실행 ID: ${run.id}`;$('provenance').style.whiteSpace='pre-line';render();}
function visibleEvents(){return frames.filter(e=>e.frame<cursor);}
function incidents(events){const items=[];for(const e of events){if(e.event==='incident_opened'){const prediction=frames.find(x=>x.event==='prediction'&&x.frame===e.frame);items.push({id:e.incident_id,frame:e.frame,cycle:prediction?.cycle_index,score:e.anomaly_score,events:[]});}const item=items.find(x=>x.id===e.incident_id);if(item)item.events.push(e);}return items.map(x=>({...x,recovered:x.events.some(e=>e.event==='incident_pattern_recovered'),action:x.events.find(e=>e.event==='action_result')}));}
function chart(predictions,key,target,isScore=false){const w=700,h=isScore?135:210,left=47,right=13,top=14,bottom=27;const values=predictions.map(p=>isScore?p.anomaly_score:p.features[key]);let min=Math.min(...values, isScore?0:Infinity),max=Math.max(...values,isScore?0:-Infinity);if(!values.length){$(target).innerHTML='<div class="empty">재생을 시작하면 측정 기록이 표시됩니다.</div>';return;}let pad=(max-min)*.15||1;min-=pad;max+=pad;const x=i=>left+i/Math.max(cursor-1,1)*(w-left-right),y=v=>top+(max-v)/(max-min)*(h-top-bottom);let grid='';for(let i=0;i<4;i++){const v=min+(max-min)*i/3;grid+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#edf1e9" stroke-dasharray="3 4"/><text x="${left-10}" y="${y(v)+3}" text-anchor="end" fill="#a1ae99" font-size="9">${v.toFixed(isScore?2:1)}</text>`;}const pts=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');const area=`${left},${h-bottom} ${pts} ${x(values.length-1)},${h-bottom}`;const color=isScore?'#9baf70':'#238b76';const zero=isScore?`<line x1="${left}" x2="${w-right}" y1="${y(0)}" y2="${y(0)}" stroke="#d0a363" stroke-dasharray="4 4"/><text x="${w-right}" y="${y(0)-5}" text-anchor="end" fill="#b78b51" font-size="8">기준 0</text>`:'';const dots=predictions.map((p,i)=>p.is_anomaly?`<circle cx="${x(i)}" cy="${y(values[i])}" r="${isScore?2.7:3}" fill="#d8a151" stroke="white" stroke-width="1"><title>윈도 ${i+1} · 사이클 ${p.cycle_index} · ${values[i].toFixed(4)}${p.contains_synthetic_samples?' · 합성 값 포함':''}</title></circle>`:'').join('');let ticks='';for(const i of [...new Set([0,Math.floor((cursor-1)/3),Math.floor(2*(cursor-1)/3),cursor-1])]){ticks+=`<text x="${x(i)}" y="${h-6}" text-anchor="middle" fill="#a1ae99" font-size="8">${i+1}</text>`;}$(target).innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="fill-${target}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".13"/><stop offset="100%" stop-color="${color}" stop-opacity=".01"/></linearGradient></defs>${grid}<polygon points="${area}" fill="url(#fill-${target})"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.8" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>${zero}${dots}${ticks}</svg>`;}
function render(){const events=visibleEvents(),predictions=events.filter(e=>e.event==='prediction'),items=incidents(events),anomalies=predictions.filter(p=>p.is_anomaly).length,actions=events.filter(e=>e.event==='action_result');$('windows').innerHTML=`${predictions.length}<small> windows</small>`;$('anomalies').innerHTML=`${anomalies}<small> windows</small>`;$('anomaly-ratio').textContent=`전체 윈도 중 ${predictions.length?(anomalies/predictions.length*100).toFixed(1):'0.0'}%`;$('incident-count').innerHTML=`${items.length}<small> incidents</small>`;$('open-count').textContent=`관찰 중 ${items.filter(x=>!x.recovered).length}건 · 패턴 복귀 ${items.filter(x=>x.recovered).length}건`;$('actions').innerHTML=`${actions.length}<small> requests</small>`;$('action-summary').textContent=`${actions.filter(x=>x.status==='applied').length}회 적용 · ${actions.filter(x=>x.status==='already_applied').length}회 기존 상태 유지`;$('nav-count').textContent=items.length;$('position').value=cursor;$('position-label').textContent=`${cursor} / ${$('position').max}`;$('signal-label').textContent=labels[signal];$('cycle-range').textContent=`사이클 위치 3–4 · ${run.offset===null?'합성 값 없음':`평가 데이터 일부에 온도 +${run.offset} 합성 값 포함`}`;chart(predictions,signal,'telemetry-chart');chart(predictions,null,'score-chart',true);$('mini-bars').innerHTML=predictions.slice(-16).map(x=>`<i style="height:${Math.min(24,4+Math.abs(x.anomaly_score)*90)}px"></i>`).join('');const steps=[['01','데이터 수집 / 검증',`${predictions.length}개 평가 윈도 · 원천 파일 보존`],['02','ML 이상 탐지',`${anomalies}개 이상 윈도 · 참조 모델 고정`],['03','사건 생성 / 문서 조회',`${items.length}건 사건 · 학습 대응 문서 매핑`],['04','모의 냉각 / 콘솔 알림',`${actions.length}회 요청 · ${events.filter(e=>e.event==='notification').length}건 로그 알림`]];$('pipeline').innerHTML=steps.map(([n,title,desc])=>`<div class="pipeline-step"><span class="step-icon">${n}</span><div><strong>${title}</strong><p>${desc}</p></div><span>기록</span></div>`).join('');renderTable(items);}
function renderTable(items=incidents(visibleEvents())){const filter=$('filter').value,query=$('search').value.trim().toLowerCase();const shown=items.filter(i=>(filter==='all'||(filter==='open'?!i.recovered:i.recovered))&&i.id.toLowerCase().includes(query));$('table-count').textContent=shown.length;$('incident-rows').innerHTML=shown.length?shown.map(i=>`<tr data-id="${esc(i.id)}" tabindex="0" role="button" aria-label="사건 ${esc(i.id.split(':').pop())} 상세"><td>INC-${run.date.slice(2).replaceAll('-','')}-${String(i.id.split(':').pop()).padStart(3,'0')}</td><td>윈도 ${i.frame+1} · 사이클 ${i.cycle}</td><td><span class="anomaly-dot"></span> 다변량 측정 이상</td><td>${i.action?esc(statuses[i.action.status]||i.action.status):'대응 기록 없음'}</td><td><span class="badge ${i.recovered?'':'open'}">${i.recovered?'패턴 복귀':'관찰 중'}</span></td><td>↗</td></tr>`).join(''):'<tr><td colspan="6" class="empty">조건에 맞는 사건이 없습니다.</td></tr>';document.querySelectorAll('tr[data-id]').forEach(row=>{row.onclick=()=>detail(row.dataset.id);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(row.dataset.id);}};});}
function detail(id){const item=incidents(visibleEvents()).find(i=>i.id===id);if(!item)return;stop();$('detail-content').innerHTML=`<h2>측정 이상 사건 #${esc(id.split(':').pop())}</h2><div class="detail-meta">실행 ${esc(run.id)}<br>윈도 ${item.frame+1} · 이상 점수 ${item.score.toFixed(5)} · ${item.recovered?'기준 패턴 복귀':'관찰 중'}</div><h3>처리 타임라인</h3>${item.events.map(e=>`<div class="event-row"><span>${esc(eventNames[e.event]||e.event)}</span><span>${e.event==='action_result'?esc(statuses[e.status]||e.status):esc(e.channel||'기록됨')}</span></div>`).join('')}<h3>참조한 학습 문서 · learning-1</h3><pre id="manual-text"></pre><p>문서와 조치는 학습 예시이며 실제 설비에 명령을 전송하지 않습니다.</p>`;$('manual-text').textContent=item.events.some(e=>e.event==='manual_found')?dataset.manual:'선택한 시점에 문서 조회 기록이 없습니다.';$('detail').showModal();}
function navigate(target){page=target;const names={overview:'배터리 운영 개요',incidents:'사건 및 대응',model:'ML 모델',architecture:'플랫폼 구조'};document.querySelectorAll('.page').forEach(p=>p.classList.toggle('hidden',p.id!==target));document.querySelectorAll('.nav-item').forEach(p=>p.classList.toggle('active',p.dataset.page===target));$('incident-panel').classList.toggle('hidden',!['overview','incidents'].includes(target));$('page-title').textContent=names[target];$('breadcrumb').textContent=target==='overview'?'운영 개요':names[target];}
$('run').onchange=e=>selectRun(Number(e.target.value));$('play').onclick=()=>{if(timer){stop();return;}if(cursor>=Number($('position').max))cursor=0;$('play').textContent='Ⅱ 재생 일시정지';timer=setInterval(()=>{cursor=Math.min(Number($('position').max),cursor+Number($('speed').value));render();if(cursor>=Number($('position').max)){stop();toast('저장된 실행 기록 재생을 완료했습니다.');}},400);render();};$('reset').onclick=()=>{stop();cursor=0;render();};$('position').oninput=e=>{stop();cursor=Number(e.target.value);render();};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-signal]').forEach(b=>b.onclick=()=>{signal=b.dataset.signal;document.querySelectorAll('[data-signal]').forEach(t=>t.classList.toggle('selected',t===b));render();});$('search').oninput=()=>renderTable();$('filter').onchange=()=>renderTable();$('close-detail').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close();}};$('export').onclick=()=>{const payload={mode:dataset.mode,run_id:run.id,source_sha256:run.sha256,visible_windows:cursor,events:visibleEvents().map(({frame,...event})=>event)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`ess-replay-${run.date}-${cursor}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('현재 재생 위치까지의 기록을 내보냈습니다.');};
fetch('data.json').then(r=>{if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json();}).then(data=>{dataset=data;$('run').innerHTML=data.runs.map((r,i)=>`<option value="${i}">Batch ${['2017-05-12','2018-02-20','2018-04-12'].indexOf(r.date)+1} · ${r.offset===null?'원본 평가':'이상 주입 실험'}</option>`).join('');$('run').value='1';selectRun(1);}).catch(error=>{$('page-title').textContent='데이터를 불러오지 못했습니다';$('source-meta').textContent=error.message;toast('data.json과 HTTP 서버 실행 상태를 확인하세요.');$('play').disabled=true;});
